:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d45;
  --text: #f0f0f0;
  --accent: #ffcd75;
  --accent-dark: #e6b85c;
  --border: #5a5f7a;
  --danger: #ff6b6b;
  --success: #6bffb8;
  --focus: #ffcd75;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 4px 0 var(--border);
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 4px;
  letter-spacing: 1px;
}

.subtitle {
  margin: 0 0 24px;
  color: #b0b4d0;
  font-size: 0.95rem;
}

h2 {
  font-size: 1.25rem;
  margin: 0 0 12px;
  border-bottom: 2px dashed var(--border);
  padding-bottom: 6px;
}

section {
  margin-bottom: 24px;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
}

input, select {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  background: #1e2030;
  border: 2px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  transition: border-color 0.15s;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 205, 117, 0.3);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 18px;
  border: 2px solid var(--border);
  border-radius: 6px;
  background: var(--accent);
  color: #1a1c2c;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

.btn:hover {
  background: var(--accent-dark);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(2px);
}

.btn.primary {
  width: 100%;
  margin-top: 4px;
}

.btn.small {
  padding: 4px 10px;
  font-size: 0.85rem;
  background: transparent;
  color: var(--danger);
  border-color: var(--danger);
}

.btn.small:hover {
  background: var(--danger);
  color: #1a1c2c;
}

.error {
  display: block;
  color: var(--danger);
  font-size: 0.85rem;
  min-height: 1.2em;
  margin-top: 4px;
}

.expense-list {
  list-style: none;
  padding: 0;
  margin: 0;
  max-height: 180px;
  overflow-y: auto;
}

.expense-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.95rem;
}

.expense-list li:last-child {
  border-bottom: none;
}

.summary p {
  margin: 6px 0;
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
}

.summary .positive {
  color: var(--success);
}

.summary .negative {
  color: var(--danger);
}

.summary .total {
  font-weight: 700;
  border-top: 2px solid var(--border);
  padding-top: 8px;
  margin-top: 8px;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
}

const FRIENDS = ['Alice', 'Bob', 'Charlie'];
let expenses = [];

const form = document.getElementById('expense-form');
const amountInput = document.getElementById('amount');
const payerSelect = document.getElementById('payer');
const amountError = document.getElementById('amount-error');
const expenseList = document.getElementById('expense-list');
const summaryDiv = document.getElementById('summary');

function formatCents(cents) {
  return '$' + (cents / 100).toFixed(2);
}

function render() {
  renderExpenses();
  renderSummary();
}

function renderExpenses() {
  expenseList.innerHTML = '';
  if (expenses.length === 0) {
    const li = document.createElement('li');
    li.textContent = 'No expenses yet.';
    li.style.opacity = '0.6';
    expenseList.appendChild(li);
    return;
  }
  expenses.forEach((exp, index) => {
    const li = document.createElement('li');
    const desc = document.createElement('span');
    desc.textContent = `${exp.payer} paid ${formatCents(exp.amount)}`;
    const btn = document.createElement('button');
    btn.className = 'btn small';
    btn.textContent = 'Delete';
    btn.setAttribute('aria-label', `Delete expense: ${exp.payer} paid ${formatCents(exp.amount)}`);
    btn.addEventListener('click', () => {
      expenses.splice(index, 1);
      render();
    });
    li.appendChild(desc);
    li.appendChild(btn);
    expenseList.appendChild(li);
  });
}

function renderSummary() {
  const totalPaid = {};
  FRIENDS.forEach(f => totalPaid[f] = 0);
  let grandTotal = 0;
  expenses.forEach(exp => {
    totalPaid[exp.payer] += exp.amount;
    grandTotal += exp.amount;
  });

  const equalShare = Math.floor(grandTotal / FRIENDS.length);
  const remainder = grandTotal % FRIENDS.length;
  const balances = {};
  FRIENDS.forEach((f, i) => {
    const share = equalShare + (i < remainder ? 1 : 0);
    balances[f] = totalPaid[f] - share;
  });

  summaryDiv.innerHTML = '';

  FRIENDS.forEach(f => {
    const p = document.createElement('p');
    const nameSpan = document.createElement('span');
    nameSpan.textContent = f;
    const amountSpan = document.createElement('span');
    const bal = balances[f];
    if (bal > 0) {
      amountSpan.textContent = `is owed ${formatCents(bal)}`;
      amountSpan.className = 'positive';
    } else if (bal < 0) {
      amountSpan.textContent = `owes ${formatCents(-bal)}`;
      amountSpan.className = 'negative';
    } else {
      amountSpan.textContent = 'settled';
    }
    p.appendChild(nameSpan);
    p.appendChild(amountSpan);
    summaryDiv.appendChild(p);
  });

  const totalP = document.createElement('p');
  totalP.className = 'total';
  const totalLabel = document.createElement('span');
  totalLabel.textContent = 'Total spent';
  const totalAmount = document.createElement('span');
  totalAmount.textContent = formatCents(grandTotal);
  totalP.appendChild(totalLabel);
  totalP.appendChild(totalAmount);
  summaryDiv.appendChild(totalP);
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const amount = parseInt(amountInput.value, 10);
  if (isNaN(amount) || amount <= 0) {
    amountError.textContent = 'Please enter a positive whole number of cents.';
    amountInput.focus();
    return;
  }
  amountError.textContent = '';
  expenses.push({ payer: payerSelect.value, amount });
  amountInput.value = '';
  amountInput.focus();
  render();
});

render();
